export type Product = {
  sku: string
  name: string
  price: number
  inventory: number
  available: boolean
}

let catalog: Product[] = [
  {
    sku: 'SKU-LAP-01',
    name: 'Laptop',
    price: 999,
    inventory: 42,
    available: true,
  },
  {
    sku: 'SKU-PHN-02',
    name: 'Phone',
    price: 699,
    inventory: 128,
    available: true,
  },
  {
    sku: 'SKU-TAB-03',
    name: 'Tablet',
    price: 499,
    inventory: 0,
    available: false,
  },
  {
    sku: 'SKU-HDP-04',
    name: 'Headphones',
    price: 199,
    inventory: 256,
    available: true,
  },
  {
    sku: 'SKU-WCH-05',
    name: 'Watch',
    price: 299,
    inventory: 64,
    available: true,
  },
]

let lastSyncedAt: string | null = null

/** Simulated upstream read — in production this would query ERP/PIM APIs. */
export async function getAllProducts(): Promise<Product[]> {
  await new Promise((resolve) => setTimeout(resolve, 100))
  return catalog.map((p) => ({ ...p }))
}

/**
 * Simulates a large catalog sync (thousands of SKUs): slow network + writes.
 * Updates in-memory store; does not block HTTP responses when scheduled via `after()`.
 */
export async function syncCatalogFromUpstream(): Promise<void> {
  await new Promise((resolve) => setTimeout(resolve, 2500))

  catalog = catalog.map((p) => {
    const priceDelta = Math.round((Math.random() - 0.5) * 40)
    const invDelta = Math.floor((Math.random() - 0.5) * 24)
    const inventory = Math.max(0, p.inventory + invDelta)
    return {
      ...p,
      price: Math.max(1, p.price + priceDelta),
      inventory,
      available: inventory > 0,
    }
  })

  lastSyncedAt = new Date().toISOString()
}

export function getLastCatalogSyncTime(): string | null {
  return lastSyncedAt
}

