import { getCachedCatalog } from '@/lib/catalog'

/** Another admin view that reuses the same tagged catalog cache as the main catalog page. */
export default async function AdminReportsPage() {
  const products = await getCachedCatalog()
  const totalInventory = products.reduce((sum, p) => sum + p.inventory, 0)
  const availableCount = products.filter((p) => p.available).length

  return (
    <div style={{ maxWidth: 640, margin: '0 auto', padding: '2rem 1.5rem' }}>
      <p style={{ margin: 0, fontSize: '0.875rem', color: 'var(--muted)' }}>
        <a href="/admin/catalog">← Catalog</a>
      </p>
      <h1 style={{ margin: '0.75rem 0 0', fontSize: '1.5rem', fontWeight: 650 }}>
        Catalog snapshot
      </h1>
      <p style={{ color: 'var(--muted)', marginTop: '0.5rem' }}>
        This page calls the same <code style={{ color: 'var(--text)' }}>getCachedCatalog()</code>{' '}
        helper, so sync invalidation applies here too.
      </p>
      <ul
        style={{
          marginTop: '1.5rem',
          padding: '1.25rem 1.5rem',
          borderRadius: 12,
          border: '1px solid var(--border)',
          background: 'var(--surface)',
          listStyle: 'none',
        }}
      >
        <li style={{ marginBottom: '0.5rem' }}>
          <strong style={{ color: 'var(--text)' }}>{products.length}</strong>{' '}
          <span style={{ color: 'var(--muted)' }}>SKUs</span>
        </li>
        <li style={{ marginBottom: '0.5rem' }}>
          <strong style={{ color: 'var(--text)' }}>{availableCount}</strong>{' '}
          <span style={{ color: 'var(--muted)' }}>available for sale</span>
        </li>
        <li>
          <strong style={{ color: 'var(--text)' }}>{totalInventory}</strong>{' '}
          <span style={{ color: 'var(--muted)' }}>units in stock (all SKUs)</span>
        </li>
      </ul>
    </div>
  )
}

